INSERT INTO "functions" VALUES(525,373312,155,'Mem_ShutdownHandles',NULL,'fpo','high: authentic FPO extent, complete control flow and INT3 padding agree','game','reconstructed','decomp/src/mem.c','edf69cfb1fd2d860913575999d39e05e37e615c11fb1e4280e4c166836e3b59f','x86 no arguments, caller cleanup, EAX=1; callbacks one stack dword, caller cleanup, result ignored; ESI/EDI saved','EXACT','docs/ghidra/windows_handle_shutdown.md','Semantic name and mem.c association inferred. Clears initialization flag before two live ascending 200-slot scans for status exactly 1 and flags exactly 0x10000 then 0x20000. Clears status before callback. Emulator callbacks are explicit test models; native callback bodies, original compiler and layout/runtime parity unverified.',NULL);
